"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { useFieldControl } from "@/components/ui/field"

type InputOTPProps = Omit<React.ComponentProps<"input">, "value" | "defaultValue" | "onChange" | "maxLength" | "type"> & {
  /** How many digits. */
  length?: number
  /** A separator stands after every this many slots (0 for none). Three and three for six. */
  group?: number
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /**
   * How the code waits and ends. line: short baselines, three and three; whole, they ink in turn. close-up: a dot
   * waits for each digit; whole, the spaces close and the proofreader's close-up mark ties the halves into one figure.
   * lyric: each digit is read back in words under it, as lyrics sit under their notes, so you can check it aloud.
   */
  variant?: "line" | "close-up" | "lyric"
  /** Called once, when the last slot fills. */
  onComplete?: (value: string) => void
  /** Pins a state for documentation ("focus"); set on the root. */
  "data-force"?: string
}

const WORDS = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]

/**
 * One real input holds the code, so paste, autofill and the keyboard all work natively.
 * The slots only draw it. Whole, the lines ink in turn; wrong (aria-invalid), they turn crimson together.
 */
function InputOTP({
  length = 6,
  variant = "line",
  group = length % 2 === 0 ? length / 2 : length % 3 === 0 ? 3 : 0,
  value,
  defaultValue = "",
  onValueChange,
  onComplete,
  className,
  "data-force": force,
  onFocus,
  onBlur,
  onPointerUp,
  ...props
}: InputOTPProps) {
  const field = useFieldControl()
  const [own, setOwn] = React.useState(defaultValue)
  const [focused, setFocused] = React.useState(false)
  const code = (value ?? own).slice(0, length)
  const wrong = props["aria-invalid"] ?? field["aria-invalid"]
  const invalid = wrong === true || wrong === "true"
  const full = code.length === length
  const here = (focused || force?.includes("focus")) && !full ? code.length : -1

  const set = (raw: string) => {
    const next = raw.replace(/\D/g, "").slice(0, length)
    if (value === undefined) setOwn(next)
    onValueChange?.(next)
    if (next.length === length && next !== code) onComplete?.(next)
  }

  const slots: React.ReactNode[] = []
  const lyric = variant === "lyric"
  for (let i = 0; i < length; i++) {
    if (i > 0 && group > 0 && i % group === 0) slots.push(<span key={`sep${i}`} className="ot-code-sep" aria-hidden="true" />)
    slots.push(
      <span key={i} data-slot="input-otp-slot" className="ot-code-slot" style={{ "--i": i } as React.CSSProperties} data-here={i === here ? "" : undefined} aria-hidden="true">
        {code[i] ? <span key={code[i]}>{code[i]}</span> : null}
        {lyric && code[i] ? (
          <span key={`w${code[i]}`} className="ot-code-word">
            {WORDS[+code[i]]}
            {i === length - 1 ? "." : group > 0 && (i + 1) % group === 0 ? "," : null}
          </span>
        ) : null}
      </span>
    )
  }

  return (
    <div data-slot="input-otp" data-variant={variant} data-force={force} data-state={full ? (invalid ? "wrong" : "done") : undefined} className={cn("ot-code", className)}>
      <input
        inputMode="numeric"
        autoComplete="one-time-code"
        pattern={`[0-9]{${length}}`}
        {...props}
        id={props.id ?? field.id}
        aria-invalid={props["aria-invalid"] ?? field["aria-invalid"]}
        aria-describedby={props["aria-describedby"] ?? field["aria-describedby"]}
        value={code}
        onChange={(e) => set(e.target.value)}
        // A pasted code replaces what's there, so a full code fills every slot.
        onPaste={(e) => {
          e.preventDefault()
          set(e.clipboardData.getData("text"))
        }}
        onFocus={(e) => {
          setFocused(true)
          onFocus?.(e)
        }}
        onBlur={(e) => {
          setFocused(false)
          onBlur?.(e)
        }}
        // Always type at the end, so Backspace takes back the last digit.
        onPointerUp={(e) => {
          onPointerUp?.(e)
          e.currentTarget.setSelectionRange(code.length, code.length)
        }}
      />
      {slots}
    </div>
  )
}

export { InputOTP, type InputOTPProps }

@layer components {
  /* ── ot-code ── a one-time code: digits drop onto short baselines, three and three */
  .ot-code { position: relative; display: inline-flex; align-items: flex-end; gap: 0.18em; font-size: min(calc(var(--ot-f) * var(--ot-expression-scale)), 12.5vw); }
  .ot-field > .ot-code { grid-column: 1 / -1; justify-self: start; margin-top: var(--ot-space-2); }
  .ot-code > input { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; padding: 0; border: 0; opacity: 0; font-size: 16px; cursor: text; }
  .ot-code[data-force~="focus"], .ot-code > input:focus-visible { outline: 0; } /* the waiting line is the focus mark */
  .ot-code-slot {
    --c: var(--ot-accent);
    display: grid; place-items: end center; width: 0.78em; height: 1.2em; padding-bottom: 0.1em;
    font-family: var(--ot-expression); font-style: italic; line-height: 1; color: var(--ot-ink); font-variant-numeric: lining-nums;
    background:
      linear-gradient(var(--c), var(--c)) no-repeat 50% 100% / 0% var(--ot-stroke),
      linear-gradient(var(--ot-rule-strong), var(--ot-rule-strong)) no-repeat 0 100% / 100% var(--ot-hairline);
    transition: background-size var(--ot-moderato) var(--ot-exhale);
  }
  .ot-code-slot > span { animation: ot-drop-in var(--ot-moderato) var(--ot-spiccato) backwards; }
  @keyframes ot-drop-in { from { opacity: 0; translate: 0 -0.3em; } }
  .ot-code-slot[data-here] { background-size: 100% var(--ot-stroke), 100% var(--ot-hairline); }
  .ot-code-sep { align-self: center; width: var(--ot-hairline); height: 0.7em; margin-inline: 0.12em; background: var(--ot-rule-strong); rotate: 22deg; }
  .ot-code-sep:is([dir="rtl"], [dir="rtl"] *) { rotate: -22deg; }
  /* Whole: the lines ink in turn. Wrong: they turn crimson together. */
  .ot-code[data-state] .ot-code-slot { background-size: 100% var(--ot-stroke), 100% var(--ot-hairline); transition-delay: calc(var(--i, 0) * 2 * var(--ot-arpeggio)); }
  .ot-code[data-state="done"] .ot-code-slot { --c: var(--ot-ink); }
  .ot-code[data-state="wrong"] .ot-code-slot { --c: var(--ot-signal); color: var(--ot-signal); transition-delay: 0s; }
  /* ── close-up ── the proofreader's close-up mark: a dot waits for each digit (the next one in the accent); whole,
     the spaces close, the halves meet in one tight figure, and the mark's two arcs land over and under the join. */
  .ot-code[data-variant="close-up"] { gap: 0.1em; transition: gap var(--ot-moderato) var(--ot-breath); }
  .ot-code[data-variant="close-up"] .ot-code-slot {
    --c: var(--ot-rule-strong);
    width: 0.62em; background: radial-gradient(circle closest-side, var(--c) 92%, transparent) no-repeat 50% calc(100% - 0.24em) / var(--ot-dot) var(--ot-dot);
    transition: width var(--ot-moderato) var(--ot-breath);
  }
  .ot-code[data-variant="close-up"] .ot-code-slot[data-here] { --c: var(--ot-accent); }
  .ot-code[data-variant="close-up"] .ot-code-slot:not(:empty) { background: none; }
  .ot-code[data-variant="close-up"] .ot-code-sep { position: relative; align-self: stretch; width: 0.3em; height: auto; margin: 0; background: none; rotate: none; transition: width var(--ot-moderato) var(--ot-breath); }
  .ot-code[data-variant="close-up"] .ot-code-sep::before, .ot-code[data-variant="close-up"] .ot-code-sep::after {
    content: ""; position: absolute; inset-inline-start: 50%; width: 0.36em; height: 0.1em; margin-inline-start: -0.18em;
    border: var(--ot-stroke) solid var(--ot-ink); scale: 0; opacity: 0;
    transition: scale var(--ot-moderato) var(--ot-spiccato) var(--ot-moderato), opacity var(--ot-allegro) var(--ot-moderato);
  }
  .ot-code[data-variant="close-up"] .ot-code-sep::before { top: 0; translate: 0.1em 0; border-bottom: 0; border-radius: 50% 50% 0 0 / 100% 100% 0 0; } /* the join leans with the italic, so the upper arc sits a little ahead */
  .ot-code[data-variant="close-up"] .ot-code-sep::after { bottom: 0; border-top: 0; border-radius: 0 0 50% 50% / 0 0 100% 100%; }
  .ot-code[data-variant="close-up"][data-state="done"] { gap: 0; }
  .ot-code[data-variant="close-up"][data-state="done"] .ot-code-slot { width: auto; padding-inline: 0.01em 0.05em; } /* the italic leans right, so it keeps a hair on that side */
  .ot-code[data-variant="close-up"][data-state="done"] .ot-code-sep { width: 0; }
  .ot-code[data-variant="close-up"][data-state="done"] .ot-code-sep::before, .ot-code[data-variant="close-up"][data-state="done"] .ot-code-sep::after { scale: 1; opacity: 1; }

  /* ── lyric ── each digit read back in words under its line, as lyrics sit under their notes; a comma at the
     halfway breath and a full stop at the end. The words are ours, upright; the figures yours. */
  .ot-code[data-variant="lyric"] { margin-bottom: calc(var(--ot-pp) * var(--ot-pp-lh) + var(--ot-space-2)); }
  .ot-code[data-variant="lyric"] .ot-code-slot { position: relative; }
  .ot-code[data-variant="lyric"] .ot-code-slot > .ot-code-word {
    position: absolute; top: calc(100% + var(--ot-space-2)); inset-inline: -1em; text-align: center;
    font-family: var(--ot-voice); font-style: normal; font-size: var(--ot-pp); line-height: var(--ot-pp-lh); letter-spacing: var(--ot-pp-tr); color: var(--ot-graphite);
    animation: ot-read-back var(--ot-moderato) var(--ot-exhale) backwards;
  }
  @keyframes ot-read-back { from { opacity: 0; clip-path: inset(0 50%); } }
  .ot-code[data-variant="lyric"][data-state="done"] .ot-code-word { color: var(--ot-ink); }
  @media (forced-colors: active) {
    .ot-code { forced-color-adjust: none; color: CanvasText; --ot-ink: CanvasText; --ot-graphite: CanvasText; --ot-pencil: GrayText; --ot-rule-strong: GrayText; --ot-accent: Highlight; --ot-signal: CanvasText; }
  }
}
